document.querySelectorAll('[data-next]').forEach(b=>b.addEventListener('click',()=>{b.textContent=b.dataset.next;b.disabled=true}));document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-rate]').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true')}));document.querySelector('[data-survey]')?.addEventListener('click',()=>{const s=document.querySelector('.survey-status');s.textContent=document.querySelector('[aria-pressed="true"]')?'Obrigado! Avaliação concluída nesta demonstração.':'Escolha uma nota antes de enviar.'});const checks=[...document.querySelectorAll('.check input')];checks.forEach(c=>c.addEventListener('change',()=>{const n=checks.filter(x=>x.checked).length;document.querySelector('progress').value=n;document.querySelector('.check-status').textContent=n+' de 3 itens verificados'}));document.querySelector('[data-finish]')?.addEventListener('click',()=>{document.querySelector('.check-status').textContent=checks.every(c=>c.checked)?'Inspeção concluída nesta demonstração.':'Verifique os três itens para concluir.'});